CREATE TABLE dwg_header_modes (
  id INTEGER PRIMARY KEY CHECK(id = 1), header_id INTEGER NOT NULL REFERENCES dwg_header(id) CHECK(header_id = 1),
  dimension_associative INTEGER NOT NULL CHECK(dimension_associative IN (0,1)), dimension_show INTEGER NOT NULL CHECK(dimension_show IN (0,1)),
  polyline_generation INTEGER NOT NULL CHECK(polyline_generation IN (0,1)), orthographic_mode INTEGER NOT NULL CHECK(orthographic_mode IN (0,1)),
