  quick_text_mode INTEGER NOT NULL CHECK(quick_text_mode IN (0,1)), paper_space_linetype_scale INTEGER NOT NULL CHECK(paper_space_linetype_scale IN (0,1)),
  limits_check INTEGER NOT NULL CHECK(limits_check IN (0,1)), user_timer INTEGER NOT NULL CHECK(user_timer IN (0,1)),
  sketch_polyline INTEGER NOT NULL CHECK(sketch_polyline IN (0,1)), angle_direction INTEGER NOT NULL CHECK(angle_direction IN (0,1)),
