  created_at_days INTEGER NOT NULL CHECK(created_at_days BETWEEN 0 AND 4294967295), created_at_milliseconds INTEGER NOT NULL CHECK(created_at_milliseconds BETWEEN 0 AND 4294967295),
  updated_at_days INTEGER NOT NULL CHECK(updated_at_days BETWEEN 0 AND 4294967295), updated_at_milliseconds INTEGER NOT NULL CHECK(updated_at_milliseconds BETWEEN 0 AND 4294967295),
  editing_duration_days INTEGER NOT NULL CHECK(editing_duration_days BETWEEN 0 AND 4294967295), editing_duration_milliseconds INTEGER NOT NULL CHECK(editing_duration_milliseconds BETWEEN 0 AND 4294967295),
  user_timer_duration_days INTEGER NOT NULL CHECK(user_timer_duration_days BETWEEN 0 AND 4294967295), user_timer_duration_milliseconds INTEGER NOT NULL CHECK(user_timer_duration_milliseconds BETWEEN 0 AND 4294967295)
);
CREATE TABLE dwg_header_space (
  id INTEGER PRIMARY KEY CHECK(id IN (1,2)), header_id INTEGER NOT NULL REFERENCES dwg_header(id) CHECK(header_id = 1),
